type wasiDirent struct {
	name     []byte
	filetype byte
	ino      uint64
}

type WASI struct {
	args   [][]byte
	env    [][]byte
	fds    map[uint32]any
	meta   map[uint32]*wasiFdMeta
	nextFd uint32
	memory *Memory
}

func newWASI(args []string, env []string, preopens map[string]string) *WASI {
	w := &WASI{
		fds: map[uint32]any{0: os.Stdin, 1: os.Stdout, 2: os.Stderr},
		meta: map[uint32]*wasiFdMeta{
			0: {base: stdioRights, inheriting: stdioRights},
			1: {base: stdioRights, inheriting: stdioRights},
			2: {base: stdioRights, inheriting: stdioRights},
		},
	}
	for _, a := range args {
		w.args = append(w.args, []byte(a))
	}
	for _, e := range env {
		w.env = append(w.env, []byte(e))
	}
	guests := make([]string, 0, len(preopens))
	for g := range preopens {
		guests = append(guests, g)
	}
	sort.Strings(guests)
	nextFd := uint32(3)
	for _, guest := range guests {
		real := preopens[guest]
		if abs, err := filepath.Abs(real); err == nil {
			real = abs
		}
		if resolved, err := filepath.EvalSymlinks(real); err == nil {
			real = resolved
		}
		// The host path must resolve, but need not be a directory: like the
		// Ruby/Perl runtimes, a single-file preopen (e.g. "/dev/null" for the zeroperl reactor's init probe) is accepted: the guest resolves it as the preopen root itself.
		if _, err := os.Stat(real); err != nil {
			panic("preopen " + guest + " => " + preopens[guest] + ": does not exist")
		}
		w.fds[nextFd] = &wasiDir{hostPath: real, preopenName: []byte(guest)}
		w.meta[nextFd] = &wasiFdMeta{base: dirRightsBase, inheriting: dirRightsInheriting}
		nextFd++
	}
	w.nextFd = nextFd
	return w
}

// checkRight reports wasiOk if the fd holds `right`, else wasiNotcapable.
// An fd with no tracked meta (should not happen for a live fd) is permitted.
func (w *WASI) checkRight(fd uint32, right uint64) uint32 {
	if m, ok := w.meta[fd]; ok && m.base&right == 0 {
		return wasiNotcapable
	}
	return wasiOk
}

// isStdio reports whether f is one of the three inherited standard streams, which take the SPIPE/no-close special cases (in lockstep with fds 0..2).
func (w *WASI) isStdio(f *os.File) bool {
	return f == os.Stdin || f == os.Stdout || f == os.Stderr
}

func (w *WASI) wasi_clock_time_get(id uint32, precision uint64, outPtr uint32) uint32 {
	switch id {
	case 0, 1, 2, 3: // realtime / monotonic / process / thread cputime
		w.memory.i64_store(uint64(outPtr), uint64(time.Now().UnixNano()))
	default:
		return wasiInval
	}
	return wasiOk
}

func (w *WASI) wasi_fd_close(fd uint32) uint32 {
	entry, present := w.fds[fd]
	if !present {
		return wasiBadf
	}
	delete(w.fds, fd)
	if f, ok := entry.(*os.File); ok && !w.isStdio(f) {
		f.Close()
	}
	// Fds are never reused after close; a *wasiDir has no OS handle.
	return wasiOk
}

func (w *WASI) wasi_fd_fdstat_get(fd, outPtr uint32) uint32 {
	entry, present := w.fds[fd]
	if !present {
		return wasiBadf
	}
	var filetype uint32 = 4 // regular file
	if _, ok := entry.(*wasiDir); ok {
		filetype = 3 // directory
	} else if f, ok := entry.(*os.File); ok {
		if fi, err := f.Stat(); err == nil && fi.Mode()&os.ModeCharDevice != 0 {
			filetype = 2 // character device (tty)
		}
	}
	// fdstat: fs_filetype (u8) + pad + fs_flags (u16) + pad + fs_rights_base
	// (u64) + fs_rights_inheriting (u64) = 24 bytes.
	// Rights and fdflags come from the stored per-fd meta; a missing entry (should not happen for a live fd) reports the permissive all-ones.
	base, inheriting := ^uint64(0), ^uint64(0)
	var fdflags uint16
	if m, ok := w.meta[fd]; ok {
		base, inheriting, fdflags = m.base, m.inheriting, m.fdflags
	}
	w.memory.fill(uint64(outPtr), 0, 24)
	w.memory.i32_store8(uint64(outPtr), filetype)
	w.memory.i32_store16(uint64(outPtr)+2, uint32(fdflags))
	w.memory.i64_store(uint64(outPtr)+8, base)
	w.memory.i64_store(uint64(outPtr)+16, inheriting)
	return wasiOk
}

func (w *WASI) wasi_fd_seek(fd uint32, offset uint64, whence, outPtr uint32) uint32 {
	f, ok := w.fds[fd].(*os.File)
	if !ok {
		return wasiBadf
	}
	if w.isStdio(f) {
		return wasiSpipe
	}
	// WASI whence (0=set, 1=cur, 2=end) matches Go's io.Seek* values exactly.
	if whence > 2 {
		return wasiInval
	}
	if e := w.checkRight(fd, rightFdSeek); e != wasiOk {
		return e
	}
	pos, err := f.Seek(int64(offset), int(whence))
	if err != nil {
		// A negative resulting offset is EINVAL, not an I/O error (the suite distinguishes them).
		return wasiInval
	}
	w.memory.i64_store(uint64(outPtr), uint64(pos))
	return wasiOk
}

func (w *WASI) wasi_fd_write(fd, iovsPtr, iovsLen, nwrittenPtr uint32) uint32 {
	f, ok := w.fds[fd].(*os.File)
	if !ok {
		return wasiBadf
	}
	if e := w.checkRight(fd, rightFdWrite); e != wasiOk {
		return e
	}
	// APPEND is honored here rather than by opening the OS fd O_APPEND, so fd_fdstat_set_flags can turn it off at runtime: seek to end before writing.
	if m, ok := w.meta[fd]; ok && m.fdflags&fdflagAppend != 0 && !w.isStdio(f) {
		f.Seek(0, 2) // whence 2 = io.SeekEnd
	}
	written := uint32(0)
	for i := uint32(0); i < iovsLen; i++ {
		ptr := w.memory.i32_load(uint64(iovsPtr) + uint64(i)*8)
		length := w.memory.i32_load(uint64(iovsPtr) + uint64(i)*8 + 4)
		n, err := f.Write(w.memory.read_string(uint64(ptr), uint64(length)))
		written += uint32(n)
		if err != nil {
			return wasiIo
		}
	}
	w.memory.i32_store(uint64(nwrittenPtr), written)
	return wasiOk
}

func (w *WASI) wasi_proc_exit(code uint32) {
	Rt.exit(int(code))
}

